namespace LealControl.Modules.Finance.Infrastructure;

public enum FinancialAccountType { Bank, Cash, Wallet, Investment }
/// <summary>Statement = extracto CSV; Manual = carga uno a uno (no se mezclan).</summary>
public enum FinancialAccountBookingMode { Statement = 0, Manual = 1 }
public enum FinancialMovementKind { Credit, Debit }
public enum FinancialMovementOrigin { Imported = 0, System = 1 }
public enum FinancialReconciliationStatus { Available, Suggested, Reconciled, Excluded, PendingBank, MatchedToImport }
public enum ReceivedChequeStatus { Available, Deposited, Presented, Credited, UsedForPayment, Rejected, Expired, Cancelled, Issued, Debited }
public enum ChequeDirection { Received, Issued }
public sealed class ReceivedCheque { public Guid Id { get; set; } public Guid TenantId { get; set; } public string CheckNumber { get; set; } = ""; public string? EcheqId { get; set; } public string? Cmc7 { get; set; } public decimal Amount { get; set; } public string Currency { get; set; } = "ARS"; public DateTime? IssueDateUtc { get; set; } public DateTime? DueDateUtc { get; set; } public string? IssuerName { get; set; } public string? IssuerTaxId { get; set; } public string? BankName { get; set; } public string? ReceivedFrom { get; set; } public ChequeDirection Direction { get; set; } = ChequeDirection.Received; public ReceivedChequeStatus Status { get; set; } = ReceivedChequeStatus.Available; public Guid? CustomerId { get; set; } public Guid? SupplierId { get; set; } public Guid? PaymentOrderId { get; set; } public Guid? BankAccountId { get; set; } public Guid? BankMovementId { get; set; } public DateTime? DepositedAtUtc { get; set; } public DateTime? CreditedAtUtc { get; set; } public string? Notes { get; set; } public Guid? CollectionReceiptId { get; set; } public DateTime CreatedAtUtc { get; set; } }
public sealed class FinancialAccount { public Guid Id { get; set; } public Guid TenantId { get; set; } public string Name { get; set; } = ""; public string Currency { get; set; } = "ARS"; public FinancialAccountType Type { get; set; } public FinancialAccountBookingMode BookingMode { get; set; } = FinancialAccountBookingMode.Statement; public decimal OpeningBalance { get; set; } public bool IsActive { get; set; } = true; /* Para los lotes de pago por archivo (nota 69, F4). */ public string? Cbu { get; set; } /* Billetera de viáticos de un empleado de RRHH. */ public Guid? EmployeeId { get; set; } public DateTime CreatedAtUtc { get; set; } }
public sealed class FinancialMovement { public Guid Id { get; set; } public Guid TenantId { get; set; } public Guid AccountId { get; set; } public FinancialMovementKind Kind { get; set; } public decimal Amount { get; set; } public string Currency { get; set; } = "ARS"; public DateTime OperationDateUtc { get; set; } public string Description { get; set; } = ""; public string? ExternalReference { get; set; } public Guid? TransferId { get; set; } public decimal? ReportedBalance { get; set; } public FinancialReconciliationStatus ReconciliationStatus { get; set; } = FinancialReconciliationStatus.Available; public Guid? ConceptId { get; set; } public Guid? ConceptRuleId { get; set; } public FinancialClassificationStatus ClassificationStatus { get; set; } = FinancialClassificationStatus.Imported; public string? ClassificationNote { get; set; } public DateTime? ClassifiedAtUtc { get; set; } public Guid? SuggestedCounterpartyId { get; set; } public string? SuggestedCounterpartyType { get; set; } public string? LinkedEntityType { get; set; } public Guid? LinkedEntityId { get; set; } public FinancialMovementOrigin Origin { get; set; } = FinancialMovementOrigin.System; public Guid? ImportId { get; set; } public Guid? MatchedMovementId { get; set; } /* Del extracto (nota 69, F1): contraparte y código de operación del banco. */ public string? CounterpartyTaxId { get; set; } public string? CounterpartyName { get; set; } public string? BankCode { get; set; } public DateTime CreatedAtUtc { get; set; } }
public sealed class DocumentSequence { public Guid Id { get; set; } public Guid TenantId { get; set; } public string DocumentType { get; set; } = ""; public string Prefix { get; set; } = ""; public int NextNumber { get; set; } = 1; public DateTime UpdatedAtUtc { get; set; } }
public sealed class CustomerAdvance { public Guid Id { get; set; } public Guid TenantId { get; set; } public Guid CustomerId { get; set; } public Guid CollectionReceiptId { get; set; } public decimal Amount { get; set; } public decimal RemainingAmount { get; set; } public string Currency { get; set; } = "ARS"; public DateTime CreatedAtUtc { get; set; } }
public sealed class BankStatementImport { public Guid Id { get; set; } public Guid TenantId { get; set; } public Guid AccountId { get; set; } public string? FileName { get; set; } public string FileHash { get; set; } = ""; public DateTime? PeriodStart { get; set; } public DateTime? PeriodEnd { get; set; } public decimal? DeclaredOpeningBalance { get; set; } public decimal? DeclaredClosingBalance { get; set; } public decimal? ComputedClosingBalance { get; set; } public int RowsTotal { get; set; } public int RowsImported { get; set; } public int RowsDuplicated { get; set; } public int RowsRejected { get; set; } public string Status { get; set; } = "Balanced"; public DateTime CreatedAtUtc { get; set; } public string? CreatedBy { get; set; } }
public sealed class BankImportProfile { public Guid Id { get; set; } public Guid TenantId { get; set; } public Guid AccountId { get; set; } public string Name { get; set; } = "Perfil de extracto"; public string ColumnMapJson { get; set; } = "{}"; public string Delimiter { get; set; } = ";"; public string? DateFormat { get; set; } public DateTime CreatedAtUtc { get; set; } public DateTime? UpdatedAtUtc { get; set; } }
public sealed class CollectionReceipt { public Guid Id { get; set; } public Guid TenantId { get; set; } public Guid AccountId { get; set; } public Guid? CustomerId { get; set; } public Guid? InvoiceId { get; set; } public string ReceiptNumber { get; set; } = ""; public decimal Amount { get; set; } public decimal AdvanceAmount { get; set; } public string Currency { get; set; } = "ARS"; public string? InvoiceCurrency { get; set; } public decimal? InvoiceAmount { get; set; } public decimal? InvoiceExchangeRate { get; set; } public decimal? PaymentExchangeRate { get; set; } public decimal? SuggestedAdjustmentArs { get; set; } public string? SuggestedAdjustmentType { get; set; } public DateTime ReceiptDateUtc { get; set; } public string Description { get; set; } = ""; public string Status { get; set; } = "Confirmed"; public string? VoidReason { get; set; } public DateTime? VoidedAtUtc { get; set; } public DateTime CreatedAtUtc { get; set; } }
public sealed record CreateAccountRequest(string Name, string Currency, FinancialAccountType Type, decimal OpeningBalance, FinancialAccountBookingMode BookingMode = FinancialAccountBookingMode.Statement);
public sealed class CollectionReceiptLine { public Guid Id { get; set; } public Guid TenantId { get; set; } public Guid ReceiptId { get; set; } public string Method { get; set; } = ""; public decimal Amount { get; set; } public string Currency { get; set; } = "ARS"; public Guid? AccountId { get; set; } public Guid? BankMovementId { get; set; } public Guid? ChequeId { get; set; } public Guid? ConceptId { get; set; } public string? RetentionType { get; set; } public string? RetentionCertificate { get; set; } public string? Jurisdiction { get; set; } public string? Notes { get; set; } public DateTime CreatedAtUtc { get; set; } }
public sealed class CollectionReceiptImputation { public Guid Id { get; set; } public Guid TenantId { get; set; } public Guid ReceiptId { get; set; } public Guid InvoiceId { get; set; } public string InvoiceNumber { get; set; } = ""; public decimal InvoiceTotal { get; set; } public decimal AmountImputed { get; set; } public decimal? AmountUsd { get; set; } public decimal? InvoiceExchangeRate { get; set; } public decimal? PaymentExchangeRate { get; set; } public decimal? ExchangeDifferenceArs { get; set; } public string Status { get; set; } = "Active"; public DateTime CreatedAtUtc { get; set; } }
public sealed record CreateMovementRequest(Guid AccountId, FinancialMovementKind Kind, decimal Amount, string Currency, DateTime OperationDateUtc, string Description, string? ExternalReference);
public sealed record TransferRequest(Guid FromAccountId, Guid ToAccountId, decimal Amount, string Currency, DateTime OperationDateUtc, string Description);

public sealed class PaymentOrder { public Guid Id { get; set; } public Guid TenantId { get; set; } public Guid? SupplierId { get; set; } public string SupplierName { get; set; } = ""; public string? SupplierTaxId { get; set; } public string OrderNumber { get; set; } = ""; public decimal Amount { get; set; } public decimal AdvanceAmount { get; set; } public string Currency { get; set; } = "ARS"; public DateTime PaymentDateUtc { get; set; } public string? Notes { get; set; } public string Status { get; set; } = "Confirmed"; public string? VoidReason { get; set; } public DateTime? VoidedAtUtc { get; set; } public DateTime CreatedAtUtc { get; set; } }
public sealed class PaymentOrderLine { public Guid Id { get; set; } public Guid TenantId { get; set; } public Guid PaymentOrderId { get; set; } public string Method { get; set; } = ""; public decimal Amount { get; set; } public string Currency { get; set; } = "ARS"; public Guid? AccountId { get; set; } public Guid? BankMovementId { get; set; } public Guid? ChequeId { get; set; } public Guid? ConceptId { get; set; } public string? RetentionType { get; set; } public string? RetentionCertificate { get; set; } public string? Notes { get; set; } public DateTime CreatedAtUtc { get; set; } }
public sealed class PaymentOrderImputation { public Guid Id { get; set; } public Guid TenantId { get; set; } public Guid PaymentOrderId { get; set; } public Guid PurchaseInvoiceId { get; set; } public string InvoiceNumber { get; set; } = ""; public decimal InvoiceTotal { get; set; } public decimal AmountImputed { get; set; } public DateTime CreatedAtUtc { get; set; } }

public sealed class FinanceDbContext(DbContextOptions<FinanceDbContext> options) : DbContext(options)
{
    public const string Schema = "finance";
    public DbSet<FinancialAccount> Accounts => Set<FinancialAccount>();
    public DbSet<WithholdingSettings> WithholdingSettings => Set<WithholdingSettings>();
    public DbSet<WithholdingRegime> WithholdingRegimes => Set<WithholdingRegime>();
    public DbSet<SupplierWithholdingProfile> SupplierWithholdingProfiles => Set<SupplierWithholdingProfile>();
    public DbSet<Withholding> Withholdings => Set<Withholding>();
    public DbSet<SufferedTaxJurisdiction> SufferedTaxJurisdictions => Set<SufferedTaxJurisdiction>();
    public DbSet<SupplierBankAccount> SupplierBankAccounts => Set<SupplierBankAccount>();
    public DbSet<PaymentBatch> PaymentBatches => Set<PaymentBatch>();
    public DbSet<PaymentBatchItem> PaymentBatchItems => Set<PaymentBatchItem>();
    public DbSet<InvestmentFund> InvestmentFunds => Set<InvestmentFund>();
    public DbSet<InvestmentFundOperation> InvestmentFundOperations => Set<InvestmentFundOperation>();
    public DbSet<ExpenseReport> ExpenseReports => Set<ExpenseReport>();
    public DbSet<ExpenseReportLine> ExpenseReportLines => Set<ExpenseReportLine>();
    public DbSet<ExpensePolicy> ExpensePolicies => Set<ExpensePolicy>();
    public DbSet<FinancialMovement> Movements => Set<FinancialMovement>();
    public DbSet<CollectionReceipt> CollectionReceipts => Set<CollectionReceipt>();
    public DbSet<CollectionReceiptLine> CollectionReceiptLines => Set<CollectionReceiptLine>();
    public DbSet<CollectionReceiptImputation> CollectionReceiptImputations => Set<CollectionReceiptImputation>();
    public DbSet<ReceivedCheque> ReceivedCheques => Set<ReceivedCheque>();
    public DbSet<FinancialConcept> FinancialConcepts => Set<FinancialConcept>();
    public DbSet<FinancialConceptRule> FinancialConceptRules => Set<FinancialConceptRule>();
    public DbSet<PaymentOrder> PaymentOrders => Set<PaymentOrder>();
    public DbSet<PaymentOrderLine> PaymentOrderLines => Set<PaymentOrderLine>();
    public DbSet<PaymentOrderImputation> PaymentOrderImputations => Set<PaymentOrderImputation>();
    public DbSet<BankStatementImport> BankStatementImports => Set<BankStatementImport>();
    public DbSet<BankImportProfile> BankImportProfiles => Set<BankImportProfile>();
    public DbSet<DocumentSequence> DocumentSequences => Set<DocumentSequence>();
    public DbSet<CustomerAdvance> CustomerAdvances => Set<CustomerAdvance>();
    protected override void OnModelCreating(ModelBuilder modelBuilder) { modelBuilder.HasDefaultSchema(Schema);
        modelBuilder.Entity<WithholdingSettings>(b => { b.ToTable("WithholdingSettings"); b.HasKey(x => x.Id); b.Property(x => x.DefaultJurisdiction).HasMaxLength(3); b.HasIndex(x => x.TenantId).IsUnique(); });
        modelBuilder.Entity<SufferedTaxJurisdiction>(b => { b.ToTable("SufferedTaxJurisdictions"); b.HasKey(x => x.Id); b.Property(x => x.SourceType).HasMaxLength(20); b.Property(x => x.Jurisdiction).HasMaxLength(3); b.HasIndex(x => new { x.TenantId, x.SourceType, x.SourceId }).IsUnique(); });
        modelBuilder.Entity<SupplierBankAccount>(b => { b.ToTable("SupplierBankAccounts"); b.HasKey(x => x.Id); b.Property(x => x.Cbu).HasMaxLength(22); b.Property(x => x.Alias).HasMaxLength(40); b.HasIndex(x => new { x.TenantId, x.SupplierId }).IsUnique(); });
        modelBuilder.Entity<PaymentBatch>(b => { b.ToTable("PaymentBatches"); b.HasKey(x => x.Id); b.Property(x => x.AccountCbu).HasMaxLength(22); b.Property(x => x.Total).HasPrecision(18, 2); b.Property(x => x.Status).HasMaxLength(20); b.Property(x => x.CreatedBy).HasMaxLength(120); b.HasIndex(x => new { x.TenantId, x.Number }).IsUnique(); b.HasMany(x => x.Items).WithOne().HasForeignKey(x => x.BatchId); });
        modelBuilder.Entity<ExpenseReport>(b => { b.ToTable("ExpenseReports"); b.HasKey(x => x.Id); b.Property(x => x.Number).HasMaxLength(40); b.Property(x => x.EmployeeName).HasMaxLength(200); b.Property(x => x.VehiclePlate).HasMaxLength(30); b.Property(x => x.ServiceOrderLabel).HasMaxLength(240); b.Property(x => x.UsdRate).HasPrecision(18, 4); b.Property(x => x.Status).HasMaxLength(20); b.Property(x => x.Notes).HasMaxLength(1000); b.Property(x => x.ApprovedBy).HasMaxLength(120); b.HasIndex(x => new { x.TenantId, x.EmployeeId, x.WeekStart }); b.HasMany(x => x.Lines).WithOne().HasForeignKey(x => x.ReportId); });
        modelBuilder.Entity<ExpenseReportLine>(b => { b.ToTable("ExpenseReportLines"); b.HasKey(x => x.Id); b.Property(x => x.Category).HasMaxLength(30); b.Property(x => x.SupplierName).HasMaxLength(200); b.Property(x => x.SupplierTaxId).HasMaxLength(11); b.Property(x => x.VoucherType).HasMaxLength(20); b.Property(x => x.VoucherNumber).HasMaxLength(40); b.Property(x => x.Amount).HasPrecision(18, 2); b.Property(x => x.Liters).HasPrecision(12, 3); b.Property(x => x.Detail).HasMaxLength(500); b.HasIndex(x => x.PurchaseInvoiceId); });
        modelBuilder.Entity<ExpensePolicy>(b => { b.ToTable("ExpensePolicies"); b.HasKey(x => x.Id); foreach (var p in new[] { nameof(ExpensePolicy.MealUsd), nameof(ExpensePolicy.SnackUsd), nameof(ExpensePolicy.LodgingOneUsd), nameof(ExpensePolicy.LodgingTwoUsd) }) b.Property(p).HasPrecision(12, 2); b.HasIndex(x => x.TenantId).IsUnique(); });
        modelBuilder.Entity<InvestmentFund>(b => { b.ToTable("InvestmentFunds"); b.HasKey(x => x.Id); b.Property(x => x.Name).HasMaxLength(120); b.Property(x => x.Currency).HasMaxLength(8); b.Property(x => x.OpeningUnits).HasPrecision(20, 6); b.Property(x => x.OpeningCost).HasPrecision(18, 2); b.Property(x => x.LastUnitValue).HasPrecision(18, 6); b.HasIndex(x => new { x.TenantId, x.Name, x.Currency }).IsUnique(); });
        modelBuilder.Entity<InvestmentFundOperation>(b => { b.ToTable("InvestmentFundOperations"); b.HasKey(x => x.Id); b.Property(x => x.ExternalId).HasMaxLength(40); b.Property(x => x.Kind).HasMaxLength(20); b.Property(x => x.Status).HasMaxLength(30); b.Property(x => x.Amount).HasPrecision(18, 2); b.Property(x => x.Units).HasPrecision(20, 6); b.Property(x => x.UnitValue).HasPrecision(18, 6); b.HasIndex(x => new { x.TenantId, x.ExternalId }).IsUnique(); b.HasOne<InvestmentFund>().WithMany().HasForeignKey(x => x.FundId); });
        modelBuilder.Entity<PaymentBatchItem>(b => { b.ToTable("PaymentBatchItems"); b.HasKey(x => x.Id); b.Property(x => x.PaymentOrderNumber).HasMaxLength(40); b.Property(x => x.SupplierName).HasMaxLength(200); b.Property(x => x.SupplierTaxId).HasMaxLength(11); b.Property(x => x.Cbu).HasMaxLength(22); b.Property(x => x.Amount).HasPrecision(18, 2); b.HasIndex(x => x.MovementId); });
        modelBuilder.Entity<WithholdingRegime>(b => { b.ToTable("WithholdingRegimes"); b.HasKey(x => x.Id); b.Property(x => x.Code).HasMaxLength(3); b.Property(x => x.Name).HasMaxLength(200); b.Property(x => x.Source).HasMaxLength(300); b.Property(x => x.NonTaxableAmount).HasPrecision(18, 2); b.Property(x => x.MinimumWithholding).HasPrecision(18, 2); b.Property(x => x.RateRegistered).HasPrecision(9, 4); b.Property(x => x.RateUnregistered).HasPrecision(9, 4); b.HasIndex(x => new { x.TenantId, x.Code }).IsUnique(); });
        modelBuilder.Entity<SupplierWithholdingProfile>(b => { b.ToTable("SupplierWithholdingProfiles"); b.HasKey(x => x.Id); b.Property(x => x.Condition).HasMaxLength(20); b.Property(x => x.RegimeCode).HasMaxLength(3); b.HasIndex(x => new { x.TenantId, x.SupplierId }).IsUnique(); });
        modelBuilder.Entity<Withholding>(b => { b.ToTable("Withholdings"); b.HasKey(x => x.Id); foreach (var p in new[] { nameof(Withholding.PaymentAmount), nameof(Withholding.Base), nameof(Withholding.PriorBase), nameof(Withholding.PriorWithheld), nameof(Withholding.NonTaxableAmount), nameof(Withholding.Amount) }) b.Property(p).HasPrecision(18, 2); b.Property(x => x.Rate).HasPrecision(9, 4); b.HasIndex(x => new { x.TenantId, x.SupplierId, x.RegimeCode, x.Date }); b.HasIndex(x => x.PaymentOrderId); }); modelBuilder.Entity<FinancialAccount>(b => { b.ToTable("FinancialAccounts"); b.HasKey(x => x.Id); b.Property(x => x.Name).HasMaxLength(180).IsRequired(); b.Property(x => x.Currency).HasMaxLength(8).IsRequired(); b.Property(x => x.OpeningBalance).HasPrecision(18, 2); b.Property(x => x.BookingMode).HasConversion<int>(); b.Property(x => x.Cbu).HasMaxLength(22); b.HasIndex(x => new { x.TenantId, x.Name }); }); modelBuilder.Entity<FinancialMovement>(b => { b.ToTable("FinancialMovements"); b.HasKey(x => x.Id); b.Property(x => x.Amount).HasPrecision(18, 2); b.Property(x => x.Currency).HasMaxLength(8); b.Property(x => x.Description).HasMaxLength(500); b.Property(x => x.ExternalReference).HasMaxLength(180); b.Property(x => x.CounterpartyTaxId).HasMaxLength(11); b.Property(x => x.CounterpartyName).HasMaxLength(160); b.Property(x => x.BankCode).HasMaxLength(20); b.HasIndex(x => new { x.TenantId, x.AccountId, x.OperationDateUtc }); b.HasIndex(x => x.ImportId); }); modelBuilder.Entity<BankStatementImport>(b => { b.ToTable("BankStatementImports"); b.HasKey(x => x.Id); b.Property(x => x.FileName).HasMaxLength(260); b.Property(x => x.FileHash).HasMaxLength(64).IsRequired(); b.Property(x => x.Status).HasMaxLength(20).IsRequired(); b.Property(x => x.DeclaredOpeningBalance).HasPrecision(18, 2); b.Property(x => x.DeclaredClosingBalance).HasPrecision(18, 2); b.Property(x => x.ComputedClosingBalance).HasPrecision(18, 2); b.Property(x => x.CreatedBy).HasMaxLength(120); b.HasIndex(x => new { x.TenantId, x.AccountId, x.FileHash }).IsUnique(); }); modelBuilder.Entity<BankImportProfile>(b => { b.ToTable("BankImportProfiles"); b.HasKey(x => x.Id); b.Property(x => x.Name).HasMaxLength(120).IsRequired(); b.Property(x => x.ColumnMapJson).HasMaxLength(4000).IsRequired(); b.Property(x => x.Delimiter).HasMaxLength(4).IsRequired(); b.Property(x => x.DateFormat).HasMaxLength(40); b.HasIndex(x => new { x.TenantId, x.AccountId }); }); modelBuilder.Entity<CollectionReceipt>(b => { b.ToTable("CollectionReceipts"); b.HasKey(x => x.Id); b.Property(x => x.Amount).HasPrecision(18, 2); b.Property(x => x.Currency).HasMaxLength(8).IsRequired(); b.Property(x => x.ReceiptNumber).HasMaxLength(40).IsRequired(); b.Property(x => x.Description).HasMaxLength(500).IsRequired(); b.Property(x => x.Status).HasMaxLength(30).IsRequired(); }); }
}

public static class DependencyInjection
{
    public static IServiceCollection AddFinanceModule(this IServiceCollection services, IConfiguration configuration)
    {
        services.AddSingleton<LealControl.BuildingBlocks.Notices.INoticeProvider, ChequesToDepositNotices>();
        services.AddFinanceApplication();
        services.AddMediatR(cfg => cfg.RegisterServicesFromAssembly(typeof(FinanceDbContext).Assembly));
        services.AddTenantDbContext<FinanceDbContext>(FinanceDbContext.Schema);
        return services;
    }
    public static IEndpointRouteBuilder MapFinanceModule(this IEndpointRouteBuilder endpoints)
    { var group = endpoints.MapGroup("/api/v1/finance").WithTags("Finance").RequirePolicyOnWrites("RequireFinance"); group.MapGet("/accounts", async (FinanceDbContext db, ITenantContext tenant, CancellationToken ct) => { var id = tenant.TenantId.Value; var accounts = await db.Accounts.AsNoTracking().Where(x => x.TenantId == id).OrderBy(x => x.Name).ToListAsync(ct); var movements = await db.Movements.AsNoTracking().Where(x => x.TenantId == id).ToListAsync(ct); var balances = movements.Where(FinanceImport.CountsTowardBankBalance).GroupBy(x => x.AccountId).ToDictionary(g => g.Key, g => new { Credit = g.Where(x => x.Kind == FinancialMovementKind.Credit).Sum(x => x.Amount), Debit = g.Where(x => x.Kind == FinancialMovementKind.Debit).Sum(x => x.Amount) }); return Results.Ok(accounts.Select(a => new { a.Id, a.Name, a.Currency, a.Type, BookingMode = a.BookingMode.ToString(), IsActive = a.IsActive, a.Cbu, a.EmployeeId, Balance = a.OpeningBalance + (balances.TryGetValue(a.Id, out var b) ? b.Credit - b.Debit : 0) })); }); group.MapPost("/accounts", async (CreateAccountRequest body, FinanceDbContext db, ITenantContext tenant, CancellationToken ct) => { var id = tenant.TenantId.Value; var account = new FinancialAccount { Id = Guid.NewGuid(), TenantId = id, Name = body.Name.Trim(), Currency = body.Currency.Trim().ToUpperInvariant(), Type = body.Type, BookingMode = body.BookingMode, OpeningBalance = body.OpeningBalance, CreatedAtUtc = DateTime.UtcNow }; db.Accounts.Add(account); await db.SaveChangesAsync(ct); return Results.Created($"/api/v1/finance/accounts/{account.Id}", account); }); group.MapPost("/movements", async (CreateMovementRequest body, FinanceDbContext db, ITenantContext tenant, CancellationToken ct) => { var id = tenant.TenantId.Value; var account = await db.Accounts.SingleOrDefaultAsync(x => x.Id == body.AccountId && x.TenantId == id && x.IsActive, ct); if (account is null) return Results.NotFound("Cuenta financiera inexistente."); if (body.Amount <= 0) return Results.BadRequest("El importe debe ser mayor a cero."); if (string.IsNullOrWhiteSpace(body.Description)) return Results.BadRequest("La descripción es obligatoria."); var movement = new FinancialMovement { Id = Guid.NewGuid(), TenantId = id, AccountId = body.AccountId, Kind = body.Kind, Amount = body.Amount, Currency = string.IsNullOrWhiteSpace(body.Currency) ? account.Currency : body.Currency.Trim().ToUpperInvariant(), OperationDateUtc = body.OperationDateUtc, Description = body.Description.Trim(), ExternalReference = string.IsNullOrWhiteSpace(body.ExternalReference) ? null : body.ExternalReference.Trim(), Origin = FinancialMovementOrigin.System, ClassificationStatus = FinancialClassificationStatus.Imported, CreatedAtUtc = DateTime.UtcNow }; if (account.BookingMode == FinancialAccountBookingMode.Statement || account.Type == FinancialAccountType.Bank) { movement.ReconciliationStatus = FinancialReconciliationStatus.PendingBank; } else { movement.ReconciliationStatus = FinancialReconciliationStatus.Available; } db.Movements.Add(movement); await db.SaveChangesAsync(ct); return Results.Created($"/api/v1/finance/movements/{movement.Id}", movement); }); group.MapPost("/transfers", async (TransferRequest body, FinanceDbContext db, ITenantContext tenant, CancellationToken ct) => { var id = tenant.TenantId.Value; if (body.FromAccountId == body.ToAccountId || body.Amount <= 0) return Results.BadRequest("Indicá cuentas distintas y un importe mayor a cero."); var accounts = await db.Accounts.Where(x => x.TenantId == id && x.IsActive && (x.Id == body.FromAccountId || x.Id == body.ToAccountId)).ToListAsync(ct); var from = accounts.SingleOrDefault(x => x.Id == body.FromAccountId); var to = accounts.SingleOrDefault(x => x.Id == body.ToAccountId); if (from is null || to is null) return Results.NotFound("Una de las cuentas no existe o está inactiva."); var currency = body.Currency.Trim().ToUpperInvariant(); if (from.Currency != currency || to.Currency != currency) return Results.BadRequest("La moneda debe coincidir con ambas cuentas."); var balances = await db.Movements.Where(x => x.TenantId == id && x.AccountId == from.Id).GroupBy(x => x.AccountId).Select(g => g.Sum(x => x.Kind == FinancialMovementKind.Credit ? x.Amount : -x.Amount)).SingleOrDefaultAsync(ct); if (from.OpeningBalance + balances < body.Amount) return Results.BadRequest("La cuenta de origen no tiene saldo suficiente."); var transferId = Guid.NewGuid(); var debitTransfer = new FinancialMovement { Id = Guid.NewGuid(), TenantId = id, AccountId = from.Id, Kind = FinancialMovementKind.Debit, Amount = body.Amount, Currency = currency, OperationDateUtc = body.OperationDateUtc, Description = body.Description.Trim(), ExternalReference = $"TRANSFER:{transferId}", TransferId = transferId, CreatedAtUtc = DateTime.UtcNow }; var creditTransfer = new FinancialMovement { Id = Guid.NewGuid(), TenantId = id, AccountId = to.Id, Kind = FinancialMovementKind.Credit, Amount = body.Amount, Currency = currency, OperationDateUtc = body.OperationDateUtc, Description = body.Description.Trim(), ExternalReference = $"TRANSFER:{transferId}", TransferId = transferId, CreatedAtUtc = DateTime.UtcNow }; FinanceSystemMovementHelper.ApplySystemDefaults(debitTransfer, from); FinanceSystemMovementHelper.ApplySystemDefaults(creditTransfer, to); var transferConceptId = await db.FinancialConcepts.Where(x => x.TenantId == id && x.Code == "TRANSFERENCIA_PROPIA").Select(x => (Guid?)x.Id).SingleOrDefaultAsync(ct); debitTransfer.ConceptId = transferConceptId; creditTransfer.ConceptId = transferConceptId; db.Movements.AddRange(debitTransfer, creditTransfer); await db.SaveChangesAsync(ct); return Results.Ok(new { transferId, amount = body.Amount, currency }); }); FinanceImport.MapFinanceImportEndpoints(endpoints); FinanceReconciliation.MapFinanceReconciliationEndpoints(endpoints); return endpoints; }
